        return (
            isinstance(value, int)
            and not isinstance(value, bool)
            and value >= 0
        )

    def _is_positive_int(value: Any) -> bool:
        return (
            isinstance(value, int)
            and not isinstance(value, bool)
            and value >= 1
        )

    if not _is_nonneg_int(manifest["snapshot"]):
        return False
    if not _is_nonneg_int(manifest["count"]):
        return False
    if manifest["alg"] != "SHA-256":
