    if not _is_positive_int(manifest["key_version"]):
        return False
    if (
        not isinstance(manifest["signature"], str)
        or not manifest["signature"]
    ):
        return False

    filters = manifest["filters"]
    if not isinstance(filters, dict):
        return False
    if set(filters) != {
        "after",
        "limit",
        "did",
        "key_version",
        "from",
        "to",
    }:
